import sqlite3
import json
import pandas as pd

# 数据库路径配置
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db"
}

def find_late_night_food_in_sparks():
    # 步骤1：连接SQLite数据库并进行初步筛选
    conn = sqlite3.connect(sqlite_paths["business"])

    query = """
    SELECT business_id, name, stars, categories, hours, attributes
    FROM business
    WHERE city = 'Sparks'
      AND (categories LIKE '%Restaurants%' OR categories LIKE '%Food%')
      AND stars >= 3.5
      AND hours IS NOT NULL
    """

    df = pd.read_sql_query(query, conn)
    conn.close()

    late_night_places = []

    # 步骤2：解析JSON数据，筛选凌晨1点后营业或带有夜宵属性的餐厅
    for _, row in df.iterrows():
        hours_str = row['hours']
        attributes_str = row['attributes']
        is_late_night = False

        # 检查 attributes 中的 GoodForMeal -> latenight
        if attributes_str:
            try:
                attrs = json.loads(attributes_str)
                if 'GoodForMeal' in attrs:
                    meal_dict = attrs['GoodForMeal']
                    # 处理Yelp数据中常见的嵌套单引号字符串字典
                    if isinstance(meal_dict, str):
                        meal_dict = meal_dict.replace("'", '"').replace("False", "false").replace("True", "true").replace("None", "null")
                        meal_dict = json.loads(meal_dict)
                    if isinstance(meal_dict, dict) and meal_dict.get('latenight') == True:
                        is_late_night = True
            except Exception:
                pass

        # 检查 hours 中的关门时间是否在 1 AM 之后
        if hours_str and not is_late_night:
            try:
                hours = json.loads(hours_str)
                for day, time_range in hours.items():
                    if time_range == '0:0-0:0':  # 代表24小时营业
                        is_late_night = True
                        break

                    start, end = time_range.split('-')
                    end_hour = int(end.split(':')[0])
                    end_minute = int(end.split(':')[1])

                    # 如果关门时间在 1:00 AM 到 5:59 AM 之间
                    if (1 <= end_hour <= 5):
                        is_late_night = True
                        break
            except Exception:
                pass

        if is_late_night:
            late_night_places.append({
                'Name': row['name'],
                'Stars': row['stars'],
                'Categories': row['categories'],
                'Hours': row['hours']
            })

    return pd.DataFrame(late_night_places)

if __name__ == "__main__":
    try:
        result_df = find_late_night_food_in_sparks()
        if not result_df.empty:
            print(f"Found {len(result_df)} good late-night food places in Sparks open after 1 AM:\n")
            for idx, row in result_df.iterrows():
                print(f"- {row['Name']} ({row['Stars']} stars)")
                print(f"  Categories: {row['Categories']}")
                print(f"  Hours: {row['Hours']}\n")
        else:
            print("No late-night food places found in Sparks matching the criteria.")
    except Exception as e:
        print(f"An error occurred: {e}")
